public synchronized void decryptSaved(CapillaryHandler handler, Object extra) {
    List<byte[]> ciphertexts = ciphertextStorage.get();
    ciphertextStorage.clear();
    for (byte[] data : ciphertexts) {
      decrypt(data, handler, extra);
